// Generated by scripts/build-academy-data.mjs from the Season 1 production sources. Do not edit by hand.
export const ACADEMY_CONTENT = Object.freeze({"locale":"tr","lessons":[{"ep":1,"title":"Bir bitcoin o kadar pahalıyken yine de biraz alabilir miyim?","goal":"Coin adedi ile harcanan tutar arasındaki farkı ve Bitcoin'in küsuratlı (parçalı) alınabildiğini öğreneceksiniz.","task":"Alıştırma panelinde 100 harcamayı coin adedine dönüştürün. Gerçek bir emir oluşturulmaz.","answer":"0.002 BTC (komisyonlar düşülmemiştir).","takeaways":["Bir Bitcoin'in fiyatı, başlamak için gereken tutar değildir.","Bitcoin ondalıklara bölünür: 50,000 fiyattan 100 harcarsanız 0.002 BTC'ye sahip olursunuz.","Her platform kendi minimum emir tutarını ve ücretlerini belirler, önce ikisini de kontrol edin."],"quiz":{"q":"Bir bitcoin 50,000 USDT. Ücretleri yok sayarak 100 USDT harcıyorsunuz. Ne alırsınız?","options":["Hiçbir şey, tam bir coin gerekir","0.002 BTC","0.02 BTC"],"answer":1,"why":"100 ÷ 50,000 = 0.002. Bir bitcoinin bir kısmına sahip olabilirsiniz."},"transcript":[{"t":0.25,"who":"sam","text":"Tek bir coin bu kadar mı pahalı? Param bilet almaya bile yetmez."},{"t":9.25,"who":"nexubo","text":"O gördüğün tek bir tam coin'in fiyatı. Her seferinde ödemen gereken tutar bu değil. Bitcoin dijital bir varlıktır ve küsuratla tutulabilir. Genelde tek bir tam coin almazsın."},{"t":25.25,"who":"narrator","text":"Bir alıştırma yapalım. Bir bitcoin 50,000 USDT olsun ve sen 100 harca. Komisyonlar hariç, bu 0.002 bitcoin eder. Bu bugünkü piyasa fiyatı değildir."},{"t":45.25,"who":"sam","text":"Peki fiyat değiştiğinde ne olur?"},{"t":47,"who":"nexubo","text":"Tuttuğun coin miktarı aynı kalabilir ama değeri yükselip düşer. Az almak daha az risk demektir, hiç risk yok anlamına gelmez."},{"t":62.25,"who":"nexubo","text":"Bölünebilir ama her platform çok küçük emirleri kabul etmez. Minimum tutarı ve komisyonları kontrol et. Öğrenirken sanal bakiye kullan. Yatırım yapmana gerek yok."},{"t":75.25,"who":"narrator","text":"Tam bir bitcoin almak zorunda mısın? Hayır. Unutma: tek bir coin'in fiyatı başlangıç eşiği değildir."},{"t":86.25,"who":"narrator","text":"İşlemlerin çoğu USDT cinsinden fiyatlandırılır. Peki USDT gerçekten bir dolar mı? Gelecek bölümde."},{"t":92.55,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?","goal":"Stabilcoin'lerin amacını, hedeflediği sabitlemeyi ve risklerini anlamak; kripto alırken her zaman önce USDT gerekmediğini bilmek.","task":"'Banka dolar mevduatı', 'USDT' ve 'BTC'yi doğru kategorilere yerleştirin.","answer":"USDT bir stabilcoin'dir, kripto varlık türüdür. Bankadaki dolar mevduatı değildir.","takeaways":["USDT, bir dolara yakın kalmak üzere tasarlanmış bir stablecoin'dir; banka mevduatı değildir.","Borsalar varlıkları fiyatlamak ve takas etmek için onu kullanır, bu yüzden bir satış çoğu zaman USDT ile sonuçlanır.","\"Stabil\" bir tasarım hedefidir: fiyat sapabilir ve geri ödemenin koşulları vardır."],"quiz":{"q":"USDT hakkında hangi ifade doğrudur?","options":["Banka hesabınızdaki dolarlardır","Bir stablecoin'dir, yani bir tür kripto varlıktır","Bir dolardan asla uzaklaşamaz"],"answer":1,"why":"USDT doları takip etmeyi amaçlar, ancak kendi ihraççı ve platform riskleri olan bir kripto varlıktır."},"transcript":[{"t":0.25,"who":"sam","text":"Adı Tether, yani temelde bankadaki dolar gibi bir şey, değil mi?"},{"t":9.25,"who":"nexubo","text":"Hayır. USDT, yani Tether, bir stabilcoin'dir. Bir dolara yakın kalacak şekilde tasarlanmıştır. Ancak bankadaki doların değildir ve risksiz nakit sayılmaz."},{"t":25.25,"who":"narrator","text":"Borsalar fiyatlama ve takas için sıkça bunu kullanır. Bitcoin'i USDT ile alabilir, sattığında ise banka havalesi yerine USDT alabilirsin."},{"t":45.25,"who":"nexubo","text":"'Stabil' bir tasarım hedefidir, garanti değildir. Fiyat kayabilir; basım ve itfanın koşulları vardır. İhraççı ve platform risklerini de öğrenin."},{"t":62.25,"who":"sam","text":"Yani bitcoin almadan önce mutlaka USDT mi almalıyım?"},{"t":65.23,"who":"nexubo","text":"Her zaman değil. Hangi para birimlerini ve işlem çiftlerini kullanabileceğin bölgene ve platformuna bağlıdır."},{"t":75.25,"who":"narrator","text":"Bu cümledeki hata ne? Stabilcoin paranızı koruma taahhüdü değildir. Amacını bilin ve bazen stabil kalamayabileceğini unutmayın."},{"t":86.25,"who":"narrator","text":"Bu gece telefonun bozulsa coin'lerin de kaybolur mu? Bir sonraki bölümde: Coin'lerin gerçekte nerede duruyor."},{"t":92.15,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı","goal":"Saklama hizmeti veren borsa hesabı ile gözetimsiz (self-custody) cüzdanı ayırt etmek, kontrol ve kurtarma sorumluluğunu anlamak.","task":"İki senaryoyu eşleştirin: borsa giriş hesabı ve kurtarma ifadeli standart gözetimsiz cüzdan.","answer":"Kontrolün kimde olduğu ve kurtarmanın nasıl çalıştığı konusunda ayrılırlar. Kendi cüzdanını tutmak otomatik güvenlik demek değildir.","takeaways":["Borsa hesabında varlıkları ve anahtarları esas olarak platform yönetir.","Kendi kendine saklama (self-custody) cüzdanında giriş bilgilerini siz kontrol edersiniz ve kurtarma sorumluluğu sizdedir.","Seçim yapmadan önce, varlıkları taşıma yetkisini kimin kontrol ettiğini sorun."],"quiz":{"q":"Standart bir kendi kendine saklama cüzdanının kurtarma ifadesini kaybettiniz ve başka bir kurtarma yönteminiz yok. Ne olur?","options":["Destek ekibi sizin için sıfırlayabilir","Erişim kalıcı olarak kaybedilebilir","Borsa onu otomatik olarak geri yükler"],"answer":1,"why":"Kendi kendine saklamada anahtarlar sizdedir. İfade veya geçerli başka bir yöntem olmadan kimse onu sizin için kurtaramaz."},"transcript":[{"t":0.25,"who":"sam","text":"Telefonum kırıldı. Coin'lerim de paramparça mı oldu?"},{"t":9.25,"who":"nexubo","text":"Coin'lerin telefonunun içinde durmaz. Cüzdan blokzincirdeki varlıkları görmeni sağlar ve onay için anahtarları kullanır. Kurtarabilmen, cüzdan türüne ve sakladığın yedeklere bağlıdır."},{"t":32.25,"who":"narrator","text":"Saklamalı borsa hesabında varlıkları ve anahtarları platform yönetir, sen hesapla işlem yaparsın. Gözetimsiz cüzdanda yetki sendedir. Kolaylık ve sorumluluk farklı dağılır."},{"t":60.25,"who":"sam","text":"İkisinde de şifreni unutursan müşteri hizmetlerini arayıp çözebilir misin?"},{"t":63.86,"who":"nexubo","text":"Öyle düşünme. Standart kurtarma ifadeli bir cüzdanda, ifadeyi kaybedersen ve başka geçerli yöntemin yoksa destek ekibi varlıklarını geri getiremez."},{"t":84.25,"who":"nexubo","text":"Varlıkları platformda tutmak platform riski taşır. Kendin tuttuğunda ise sızdırılan anahtar veya hatalı onay yüzünden kayıp yaşanabilir. Bugün sadece farkı anla."},{"t":103.25,"who":"narrator","text":"Varlıkları transfer etme yetkisini kim kontrol ediyor? Önce buna cevap ver. Sonra hangi hesaba veya cüzdana ihtiyacın olduğuna karar ver."},{"t":116.25,"who":"narrator","text":"İki kapı da aynı görünüyor. Biri sahte. Gelecek bölümde: Gerçek kapı nasıl ayırt edilir."},{"t":121.75,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":4,"title":"Gerçek kapıyı bul: Körlemesine hesap açma","goal":"Kayıt olmadan önce resmî alan adını, bölge şartlarını kontrol etmek ve temel güvenliği açmak.","task":"Simüle edilmiş bir kayıt sayfasının adres çubuğundaki tutarsızlığı bulun.","answer":"Resmî alan adı eşleşmiyor. Şüpheli sitelere hiçbir bilgi girmeyin.","takeaways":["Her şeyden önce platformun gerçekten yaşadığınız ülkeye hizmet verdiğini kontrol edin.","Yalnızca doğrulanmış resmi giriş üzerinden, kendi e-postanız veya telefonunuzla kaydolun.","Kayıttan hemen sonra güvenlik özelliklerini açın ve kurtarma seçeneklerinizi kaydedin."],"quiz":{"q":"Kaydolmadan önce ilk olarak neyi doğrulamalısınız?","options":["Hoş geldin ödülünün büyüklüğünü","Platformun ülkenize hizmet verdiğini ve girişin resmi olduğunu","Platformun kaç takipçisi olduğunu"],"answer":1,"why":"Uygunluk ve resmi giriş önce gelir. Bir ödül, hesabınızı nerede açacağınıza asla karar vermemelidir."},"transcript":[{"t":0.25,"who":"sam","text":"İnternette 'kripto borsası' diye arattım, birbirine benzeyen on link çıktı. Hangisi gerçek?"},{"t":9.25,"who":"nexubo","text":"Körlemesine tıklama. Kaydolmadan önce dört şeyi kontrol et: resmî alan adı, bölge şartları, kullanılabilir ürünler ve hesap güvenliği."},{"t":32.25,"who":"narrator","text":"Resmî girişi doğruladıktan sonra kendi e-postan veya telefonunla kaydol, benzersiz bir şifre belirle ve doğrulamaları tamamla. Asla başkasının hesabını satın alma, kimliğini sahte beyan etme."},{"t":60.25,"who":"nexubo","text":"Kaydolmak son adım değildir. Platformun sunduğu güvenlik ayarlarını aç, giriş yapılan cihazları kontrol et ve kurtarma yollarını kaydet. Tek kullanımlık kodu asla sözde destek personeline verme."},{"t":84.25,"who":"narrator","text":"Sitemiz bilgi edinmenize yardımcı olabilir, ancak iş ortaklığı bir güvenlik garantisi değildir. Bilgiler doğrulanmadıysa hesap açma sürecine başlamayın."},{"t":103.25,"who":"sam","text":"Dur. Önce uygunluğu ve kuralları doğrula."},{"t":107.02,"who":"nexubo","text":"Doğru. Önce kapıyı tanı, sonra hesap aç."},{"t":116.25,"who":"nexubo","text":"Güvenilir bir kapı mı istiyorsun? NexuAlpha doğrulanmış resmî girişleri listeler. OKX partner bağlantımız doğrudan resmî siteye gider, nexu888 kodu komisyon iadesi sağlar."},{"t":127.35,"who":"narrator","text":"Şimdi yap: İki adımlı doğrulamayı aç. Gelecek bölümde: Sohbette biri 'senin yerine KYC yapmayı' teklif ediyor."},{"t":134.45,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":5,"title":"KYC nasıl yapılır ve kimlik kime verilmelidir?","goal":"Kimlik doğrulamanın genel amacını ve akışını anlamak, yalnızca doğrulanmış resmî kanallardan göndermek.","task":"Kurgusal bilgilerle doğrulama adımlarını sıralayın. Eğitime gerçek kimlik yüklemek yasaktır.","answer":"Resmî girişi doğrula → bölgenin gerektirdiği gerçek bilgileri gönder → bekle ve sonucu kontrol et.","takeaways":["KYC, hesap sahibinin siz olduğunuzu doğrular ve platformun kurallara uymasına yardımcı olur.","Kimliğinizi yalnızca resmi doğrulama akışı içinde gönderin, asla bir sohbette değil.","Başarısız olursa nedenini okuyun, düzeltin ve gerçek kimliğinizle tekrar deneyin."],"quiz":{"q":"Kimliğinizi kim almalı?","options":["Bir sohbet grubundaki yardımsever bir \"temsilci\"","Yalnızca doğrulanmış resmi doğrulama akışı","Başkaları kontrol edebilsin diye kurs sohbeti"],"answer":1,"why":"Yalnızca resmi akış. NexuAlpha kimliğinizi asla istemez, bir yabancı da istememelidir."},"transcript":[{"t":0.25,"who":"sam","text":"Kimliğimi istiyor. Yanımdaki bu kişi ise benim yerime halledebileceğini söylüyor?"},{"t":9.25,"who":"nexubo","text":"Kimlik doğrulaması hesap sahibini teyit etmek ve yasal kurallara uymak içindir. Önce resmî akışta olduğundan emin ol. Kimliğini ve kodları sohbet gruplarındaki 'aracılara' verme."},{"t":32.25,"who":"narrator","text":"Genelde gerçek bilgilerini girer, desteklenen geçerli bir kimlik yükler ve fotoğraf veya yüz tanıma adımlarını izlersin. Hangi belgelerin kabul edildiği bölgeye ve platforma bağlıdır."},{"t":60.25,"who":"nexubo","text":"Başarısız olursa nedenine bak: Süresi mi dolmuş? Parlama mı var? İsim mi uyuşmuyor? Talimata göre düzelt, asla sahte bir kimlikle tekrar deneme."},{"t":84.25,"who":"sam","text":"Tamamlayınca hemen işlem yapabilir miyim?"},{"t":86.78,"who":"nexubo","text":"Garanti değil. Sonuç, kullanabileceğin ürünler ve para yatırma izni resmî bildirime bağlıdır. Bu akademi de asla gerçek kimliğini toplamaz."},{"t":103.25,"who":"narrator","text":"Kimliğini kime vereceksin? Yalnızca doğrulanmış resmî akışa. Bize değil, yabancılara hiç değil."},{"t":116.25,"who":"nexubo","text":"Doğrulamaya hazır mısın? Yalnızca resmî sitede başla. OKX partner bağlantımız nexu888 koduyla komisyon iadesi sağlayarak doğrudan oraya götürür. Kimliğini asla istemeyiz."},{"t":127.25,"who":"narrator","text":"Yatır, al, transfer et: birbirine benzeyen üç buton. Gelecek bölümde: Hangisine basmalı."},{"t":132.85,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":6,"title":"İlk para yatırma: Para nereden gelir ve nereye gider?","goal":"Fiat yatırma, doğrudan alım, kripto yatırma ve dahili transferi ayırt etmek; kanalları ve ücretleri kontrol etmek.","task":"Üç senaryoyu eşleştirin: Bankadan fiat yatırma, mevcut kriptoyu yatırma ve hesaplar arası dahili transfer.","answer":"Farklı yolların kuralları, ücretleri ve süreleri farklıdır. Dahili transfer blokzincir kullanmaz.","takeaways":["İtibari para yatırma, kripto satın alma, zincir üstü yatırma ve dahili transfer farklı yollardır.","Zincir üstü yatırmalar desteklenen bir coin ve ağ gerektirir; dahili transferler platformda kalır.","Platform dışında bir yabancıya asla ödeme yapmayın; önce bakiyenin nereye düşeceğini kontrol edin."],"quiz":{"q":"Aynı platformda USDT'yi fonlama hesabınızdan işlem hesabınıza taşıyorsunuz. Bu nedir?","options":["Zincir üstü yatırma","Dahili transfer","İtibari para yatırma"],"answer":1,"why":"Yalnızca kendi hesaplarınız arasında bakiye taşır. Genellikle zincir üstü bir transfer değildir."},"transcript":[{"t":0.25,"who":"sam","text":"Üç buton var: yatır, al ve transfer et. Hepsi hesaba para koymak için değil mi?"},{"t":9.25,"who":"nexubo","text":"Hayır. Farklı varlıkları taşırlar. Yerel para mı yatırıyorsun, elindeki kriptoyu mu aktarıyorsun? Yoksa sadece kendi hesapların arasında bakiye mi kaydırıyorsun?"},{"t":32.25,"who":"narrator","text":"Fiat yatırma genelde hesabınıza nakit bakiye ekler. Doğrudan kripto almak ise ödeme yapıp varlığı teslim almaktır. Banka ve kart kanalları, ücretler ve limitler platforma göre değişir."},{"t":60.25,"who":"nexubo","text":"Zaten kripton varsa, desteklenen coin ve ağ üzerinden yatırabilirsin. Dahili transfer hesapların arasında bakiye aktarır, blokzincir işlemi değildir. Bakiyenin nereye gideceğini kontrol et."},{"t":84.25,"who":"narrator","text":"Bazı platformlar kullanıcılar arası (P2P) işlem sunar. Bu sıradan bir banka transferi değildir. Asla platform dışından özel ödeme yapma, kaynağı belirsiz fonları kullanma."},{"t":103.25,"who":"sam","text":"Hayır. Bunlar farklı kanallardır."},{"t":105.59,"who":"nexubo","text":"Doğru. Önce varlığa bak, sonra yola, en son fiilen neyin ulaştığını kontrol et."},{"t":116.25,"who":"narrator","text":"BTC/USDT: Aradaki eğik çizgi iki coin mi alıyorsun demek? Gelecek bölümde: İlk spot işlemin."},{"t":122.45,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":7,"title":"İlk spot işleminiz: 100 USDT ile 0,002 BTC alımı","goal":"Tutarı, miktarı ve komisyonu net bir simüle spot alım işlemini tamamlamak.","task":"Sanal 1,000 bakiye ile 0.002 BTC alın. Kalan 899.90 USDT bakiyesini ve işlem geçmişini kontrol edin.","answer":"Tutar 100, komisyon 0.10, toplam harcama 100.10; kalan 899.90.","takeaways":["BTC/USDT, USDT cinsinden fiyatlanan bitcoin demektir: USDT ödersiniz, bitcoin alırsınız.","Emir kutusunun bir para tutarı mı yoksa coin adedi mi istediğini kontrol edin.","Aldıktan sonra işlem kaydını kontrol edin: gerçekleşme durumu, ortalama fiyat ve ücret."],"quiz":{"q":"50.000 USDT fiyattan 0,002 BTC alıyorsunuz; %0,1 komisyon USDT olarak ayrıca kesiliyor. Toplam harcama nedir?","options":["100","100.10","110"],"answer":1,"why":"Coinler için 100 artı 0.10 ücret, 100.10 eder."},"transcript":[{"t":0.25,"who":"sam","text":"Bu eğik çizgi. İki coin'i birden mi almam gerekiyor?"},{"t":9.25,"who":"nexubo","text":"Hayır. Bu, bitcoin'in USDT cinsinden fiyatlandığı anlamına gelir. Alırken USDT öder, bitcoin alırsın. Satarken tam tersidir."},{"t":35.25,"who":"narrator","text":"Sanal hesapla pratik yapıyoruz. Vadeli değil spot olduğundan emin ol. Çifti seç, Al'a tıkla ve tutarı gir. Kutunun para tutarı mı yoksa coin adedi mi istediğine dikkat et."},{"t":67.25,"who":"nexubo","text":"Eşleşme fiyatı 50,000 olsun ve 100 harca. 0.002 bitcoin alırsın. USDT'den ayrıca kesilen 0.1% komisyon varsayarsak toplam 100.10 harcarsın. Gerçek kurallar platforma bağlıdır."},{"t":95.25,"who":"sam","text":"Yani Al'a bastığım an coin'lerin geldiği kesin mi?"},{"t":99.07,"who":"nexubo","text":"İşlem geçmişini de kontrol et. Gerçekleşmedi, kısmen gerçekleşti ve tamamen gerçekleşti farklı durumlardır. Gerçek ortalama fiyatı ve komisyonu da kontrol et."},{"t":116.25,"who":"narrator","text":"İlk alıştırmanın amacı fiyatın yönünü tahmin etmek değil, bu beş maddeyi doğrulamaktır. Bitirdiğinde hemen gerçek işlem yapmamak da gayet doğaldır."},{"t":140.95,"who":"narrator","text":"Diyelim fiyat yükseldi ve sattın. Peki banka bakiyen neden hiç değişmedi? Gelecek bölümde."},{"t":146.85,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":8,"title":"Sattım. Para neden banka hesabımda değil?","goal":"Bir varlığı satmak, stabilcoin veya fiat bakiye almak ile gerçek bir banka çekimi arasındaki farkı ayırt etmek.","task":"Simüle bir satış yapın ve para akışı şemasında hangi adımın banka çekimi olduğunu işaretleyin.","answer":"USDT'ye satmak banka çekimi değildir. Bu örnekteki net işlem sonucu: 9.79.","takeaways":["USDT karşılığında satmak size USDT bakiyesi verir, bankanızda para değil.","Satmak ve bankanıza çekmek iki ayrı adımdır.","Daha yüksek fiyat net kazancınız değildir: önce tüm ücretleri düşün."],"quiz":{"q":"Bitcoininizi USDT karşılığında sattınız. Para şimdi nerede?","options":["Banka hesabınızda","Platformda USDT bakiyesi olarak","Çoktan yerel para biriminize çevrildi"],"answer":1,"why":"USDT aldınız. Paranın bankanıza ulaşması ayrı bir çekme adımıdır."},"transcript":[{"t":0.25,"who":"sam","text":"Kesinlikle sattım. Peki banka hesabıma para neden hâlâ gelmedi?"},{"t":9.25,"who":"nexubo","text":"Önce hangi işlem çiftinde sattığına bak. USDT karşılığı sattıysan USDT bakiyesi aldın, bankaya para gelmedi. Satış yapmak ile bankaya para çekmek iki ayrı adımdır."},{"t":35.25,"who":"narrator","text":"Aynı eğitim örneği. 0.002 bitcoin'i 55,000 fiyattan satarsın, 110 eder. 0.11 varsayımsal komisyon düşüldüğünde hesabına 109.89 geçer."},{"t":67.25,"who":"sam","text":"Yani on mu kazandım?"},{"t":68.76,"who":"nexubo","text":"Maliyetleri düş. Burada kur çevrimi veya çekim ücretleri hariç 9.79 kalır. Fiyatın yükselmesi nihai net kazancınla aynı şey değildir."},{"t":95.25,"who":"narrator","text":"Parayı bankaya çekmen gerekirse, önce bölgenin desteklediğinden emin ol. Ardından kendi adına kayıtlı bir hesaba resmî yoldan çek. İsmi, hesaba geçen tutarı, ücretleri ve şartları kontrol et."},{"t":116.25,"who":"sam","text":"Hayır."},{"t":116.98,"who":"nexubo","text":"İşlem ve çekim kayıtlarını sakla. Bakiyenin niteliğinden emin değilsen, tek bir 'başarılı' bildirimine bakarak karar verme."},{"t":131.25,"who":"narrator","text":"Biraz daha ucuz bir ağ. Tek bir yanlış tıklama. Coin'lerin asla ulaşmayabilir. Gelecek bölümde: Asla tahmin etmemen gereken kontroller."},{"t":137.95,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma","goal":"Coin, ağ, adres, memo ve hesaba geçme şartlarını kontrol etmek; önce küçük bir deneme transferi yapmak.","task":"Kasıtlı hatalar içeren simüle çekim formunda ağ uyumsuzluğunu ve eksik memo'yu düzeltin; ardından sanal küçük bir test gönderin.","answer":"Yalnızca tüm kritik şartlar eşleştiğinde gönderin. Varsayılan bir 'doğru ağa otomatik geçiş' koruması yoktur.","takeaways":["Göndermeden önce alıcının desteklediği coin'i ve ağı doğrulayın.","Adresi alıcı sayfasından kopyalayın, tamamını kontrol edin ve gereken memo veya tag'i ekleyin.","Önce küçük bir test gönderin ve hesaba geçtiğini doğrulayın."],"quiz":{"q":"Alıcı sayfası bir memo istiyor. Ne yaparsınız?","options":["Atlarım, adres yeterli","Memo'yu tam olarak gösterildiği gibi girerim","Eski bir transferdeki memo'yu kullanırım"],"answer":1,"why":"Memo veya tag gerekiyorsa, transfer onsuz hesaba geçmeyebilir."},"transcript":[{"t":0.25,"who":"sam","text":"Bu ağ daha ucuzmuş. Ona geçiversem ne olur ki?"},{"t":9.25,"who":"nexubo","text":"Önce alıcının hangi varlığı ve ağı desteklediğini doğrula. Sonra komisyonu düşün. İki taraf eşleşmiyorsa sırf ucuz diye gönderme. USDT bile farklı ağlarda bulunabilir."},{"t":39.25,"who":"narrator","text":"Ağı bir rota, adresi ise varış noktası gibi düşünebilirsin. Ancak iki adres birbirine benzese bile aynı ağda çalışmayabilir. Alıcı platformun bu zinciri ve varlığı desteklediğini mutlaka kontrol et."},{"t":75.25,"who":"nexubo","text":"Alıcı sayfadan adresi kopyala ve tamamını kontrol et. Memo veya etiket isteniyorsa doldur. Minimum yatırma tutarını, çekim ücretini ve hesaba geçecek miktarı onayla. Adresi sadece başından ve sonundan okuma."},{"t":106.25,"who":"narrator","text":"Minimumu karşılayan küçük bir test gönder ve gerçekten hesaba geçtiğini doğrula. Daha büyük transferde her şeyi tekrar kontrol et, eski kayıtlara körü körüne güvenme. Gözetimsiz cüzdanda ağ ücretini de hazır bulundur."},{"t":130.25,"who":"sam","text":"Hayır."},{"t":131.16,"who":"nexubo","text":"Göndermeden önce bir kez daha kontrol etmek, hata yaptıktan sonra yardım aramaktan çok daha iyidir."},{"t":146.25,"who":"narrator","text":"'Başarılı' diyor ama hiçbir şey gelmedi. Tekrar gönderme. Gelecek bölümde: Nereye bakmalı."},{"t":151.65,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":10,"title":"Gönderildi yazıyor ama ulaşmadı. Nereye bakmalısın?","goal":"Gönderen işlemesi, zincir üstü onay ve alıcı hesabına geçmeyi ayırt etmek; sınırlı kurtarma yollarını bilmek.","task":"Üç sorun senaryosunu gönderen, zincir üstü durum ve alıcı ile eşleştirin.","answer":"Durumu tespit edip ilgili resmî kanala başvurun. Nedeni bilinmiyorsa mükerrer ödeme yapmayın.","takeaways":["Gönderildi, zincirde ve hesaba geçti üç farklı duraktır.","İşlem hash'ini doğru ağın blok gezgininde kullanın.","Kayıtları resmi destekle paylaşın; kurtarma ifadenizi, özel anahtarınızı veya kodlarınızı asla paylaşmayın."],"quiz":{"q":"Transferiniz \"gönderildi\" diyor ama ulaşmadı. İlk adım nedir?","options":["Aynı tutarı tekrar göndermek","Kaydı ve işlem hash'ini kullanarak nerede takıldığını bulmak","Kurtarmayı vaat eden birine ödeme yapmak"],"answer":1,"why":"Önce durağı bulun, sonra ilgili resmi kanala başvurun. Göndermeye devam etmeyin."},"transcript":[{"t":0.25,"who":"sam","text":"Hesaba geçmedi. Denemek için birkaç kez daha mı göndersem?"},{"t":9.25,"who":"nexubo","text":"Tekrar gönderme. Gönderildi, zincire girdi ve hesaba geçti aynı şey değildir. Önce nerede takıldığını bul, sonra kime yazacağına karar ver."},{"t":32.25,"who":"narrator","text":"Gönderim kaydını sakla. İşlem hash'i (Tx hash) varsa, o ağın resmî blok gezgininde durumunu, hedef adresini ve miktarını kontrol et. Başka zincirin arama sonucunu karıştırma."},{"t":60.25,"who":"nexubo","text":"Alıcı platform daha fazla onay veya dahili inceleme bekliyor olabilir. Coin, ağ, adres veya memo yanlışsa göndermeyi kes ve bilgileri resmî desteğe ilet."},{"t":84.25,"who":"narrator","text":"Tamamlanmış bir zincir üstü transfer geri alınamaz. Kurtarılabilmesi teknik ve platform şartlarına bağlıdır, garanti verilemez. Ücret karşılığı kesin kurtarırım diyenlere inanma."},{"t":103.25,"who":"sam","text":"Gereken işlem kayıtlarını ver. Kurtarma ifadesini, özel anahtarı veya kodları asla verme."},{"t":107.92,"who":"nexubo","text":"Doğru. Önce nerede takıldığını bul. Körlemesine tekrar transfer yapma."},{"t":116.25,"who":"narrator","text":"'Merhaba, ben destek ekibindenim. Kurtarma ifadeni gönder.' Gelecek bölümde: Dolandırıcıların asıl istediği şey."},{"t":122.45,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak.","goal":"Gizli kimlik bilgisi taleplerini, platform dışı ödemeleri, şüpheli onayları ve kâr vaatlerini tanımak.","task":"Dört kurgusal sohbetteki tehlikeli talepleri tespit edin ve 'dur ve resmî olarak doğrula' yolunu seçin.","answer":"Biri özel anahtarını, kurtarma ifadeni, kodlarını veya belirsiz bir onayı isterse asla yapma.","takeaways":["Kurtarma ifadeniz ve özel anahtarınız kontrol anahtarlarıdır, destek kodu değildir.","Garantili getiriler ve ödeme yapmanız için baskı tehlike işaretleridir.","Anlamadığınız bir imzayı veya onayı asla onaylamayın."],"quiz":{"q":"Ödeme alabilmek için hangisini paylaşmak güvenlidir?","options":["Açık (public) adresiniz","Kurtarma ifadeniz","Tek kullanımlık bir kod"],"answer":0,"why":"Açık adres, almak için yapılmıştır. Gizli bilgiler ve kodlar kontrolü başkasına verir."},"transcript":[{"t":0.25,"who":"sam","text":"Destek ekibinden olduğunu ve cüzdanımı güncelleyeceğini söylüyor."},{"t":9.25,"who":"nexubo","text":"Standart bir cüzdanda kurtarma ifadesi ana kontrol yetkisidir, destek kodu değildir. Özel anahtar da öyledir. Asla kimseye verme. Akademi asistanımız bile bunu isteyemez."},{"t":32.25,"who":"narrator","text":"İki tehlike işareti daha: Garanti kazanç vaadi ve acele ödeme baskısı. Yüksek kâr ekran görüntüleri hiçbir şeyi kanıtlamaz. Biri seni normal kontrolleri atlamaya zorlarsa dur."},{"t":60.25,"who":"nexubo","text":"Cüzdan bağlamak, mesaj imzalamak ve varlık erişimini onaylamak farklı şeylerdir. İmzayı veya onayı anlamıyorsan onaylama. Şifre sormaması risksiz olduğu anlamına gelmez."},{"t":84.25,"who":"narrator","text":"Bir sızıntıdan şüphelenirsen dur ve resmî güvenlik kanallarını kullan. Neyin sızdığına göre hedefli önlem al, kimsenin yönlendirmesiyle uzaktan kontrol yazılımı indirme."},{"t":103.25,"who":"sam","text":"Para almak için bilgi paylaşmak, kontrol yetkisini teslim etmekle aynı şey değildir."},{"t":106.72,"who":"nexubo","text":"Sırlarını paylaşma. Anlamadığın şeye onay verme. Aceleyle ödeme yapmaya zorlanma."},{"t":116.25,"who":"narrator","text":"On bir bölüm bitti. Gerçek para yatırma zamanı geldi mi? 1. Sezon finali şaşırtıcı bir cevaba sahip."},{"t":123.15,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":12,"title":"1. Sezon Finali: Yapabilirsin ve işlem yapmamayı da seçebilirsin","goal":"Entegre alıştırmayı tamamlamak, işlem yapmamanın da geçerli bir seçenek olduğunu anlamak ve sonraki adımları bilmek.","task":"Alıştırma panelinde kursun son üç sorusunu yanıtlayın.","answer":"USDT'ye satmak banka çekimi değildir; zincire girmek hesaba geçmek demek değildir; kimlik bilgilerini paylaşma ve şüphedeysen transfer yapma.","takeaways":["Hedef doğru bir akıştır: giriş ve uygunluk, spot, tutar ve ücret, ardından kayıt.","Belirsiz bir transferi durdurmak da doğru bir cevaptır.","Sertifikanız bir öğrenme kaydıdır, yatırım ehliyeti değildir."],"quiz":{"q":"Bir alıştırma transferi yanlış ağı gösteriyor. Doğru hamle nedir?","options":["Yine de gönderip umut etmek","Durmak ve göndermemek","Daha büyük bir tutara geçmek"],"answer":1,"why":"Ağ, ücretler veya kimlik belirsiz olduğunda, durmak görevi bitirmekten daha önemlidir."},"transcript":[{"t":0.25,"who":"sam","text":"Bütün dersleri bitirdim. Bu artık gerçek işlem yapmaya hazır olduğum anlamına mı gelir?"},{"t":9.25,"who":"nexubo","text":"Acele etme. Bugün kapsamlı bir simülasyon yapacağız. Giriş kapısını, spotu, tutarı ve komisyonu kontrol et, kaydı incele. Şüphen varsa işlem yapma."},{"t":39.25,"who":"narrator","text":"Doğru yapmak, riskleri tanımak ve sakince kontrol etmektir. Alıştırma puanı gelecekteki kârın garantisi değildir. Yanlış yaparsan ilgili dersi tekrar izle."},{"t":75.25,"who":"sam","text":"Bu transfer bilgisinde bir gariplik var. Göndermiyorum."},{"t":78.5,"who":"nexubo","text":"Bu da doğru bir cevap. Ağ, ücretler veya kimlik net değilse, durmak görevi zorla tamamlamaktan çok daha önemlidir."},{"t":106.25,"who":"narrator","text":"Son olarak şu üç soruyu yanıtla: Varlık nereye gitti? Gerçekte ne kadar kesildi? Hesabını kim kontrol ediyor? Birini açıklayamıyorsan o bölüme dönüp tekrar çalış."},{"t":130.25,"who":"nexubo","text":"Kazandığın şey bir öğrenme kaydıdır, yatırım yetki belgesi değil. Öğrenmeye devam edebilirsin ya da şimdilik işlem yapmayabilirsin. İkisi de doğrudur. Önce anla, sonra harekete geç."},{"t":146.25,"who":"nexubo","text":"Başlamaya karar verdiğinde, NexuAlpha'da borsaları karşılaştır. Kodumuzla resmî partner bağlantısından kaydolup komisyon iadesi al ve yeni dersler için Telegram'ımıza katıl."},{"t":157.55,"who":"narrator","text":"2. Sezon: Ekrandaki fiyat her zaman ödediğin fiyat değildir. Nedenini öğren."},{"t":163.05,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":13,"title":"Ekrandaki fiyat neden benim gerçekleşen fiyatım değil?","goal":"Emir defterini, alış-satış makasını (spread), piyasa derinliğini, komisyonları ve kaymayı (slippage) anlamak.","task":"0.002 BTC'yi iki kademeli sanal satış emriyle eşleştirin ve ağırlıklı ortalama fiyatı hesaplayın.","answer":"Toplam 100.10, eğitim komisyonu öncesi ortalama 50,050. 0.1% USDT komisyonu eklenirse: komisyon 0.1001, toplam harcama 100.2001 (önceden yuvarlamayın).","takeaways":["Son fiyat en son gerçekleşen işlemdir, her büyüklük için geçerli bir teklif değildir.","Daha büyük emirler emir defterinin birkaç seviyesinde gerçekleşebilir.","Kayma (slippage) ve işlem ücreti ayrı maliyetlerdir: faturayı kontrol edin."],"quiz":{"q":"0.002 BTC'nizin yarısı 50,000'den, diğer yarısı 50,100'den gerçekleşiyor. Ortalama fiyatınız nedir?","options":["50,000","50,050","50,100"],"answer":1,"why":"İki eşit yarının ortalaması 50,050'dir. Ücret bunun üzerine ayrı bir maliyettir."},"transcript":[{"t":0.25,"who":"sam","text":"Bir saniye önce bu fiyattaydı. Faturam neden farklı çıktı?"},{"t":9.25,"who":"nexubo","text":"Ekrandaki son fiyat en son gerçekleşen işlemin kaydıdır, sınırsız miktarda bir teklif değildir. Şu an insanların ne kadar alıp satmak istediği emir defterindedir."},{"t":32.25,"who":"narrator","text":"0.002 bitcoin aldığını düşün. İlk kademede sadece yarısı var. Diğer yarısı daha yüksek fiyattan eşleşir. Birlikte ortalama 50,000 değil 50,050 olur."},{"t":60.25,"who":"nexubo","text":"Kayma (slippage), beklediğin fiyat ile aldığın fiyat arasındaki farktır. Her zaman aleyhine olmaz. Komisyon ise ayrı bir maliyettir. Bunları 'sıfır komisyon' sloganında birleştirme."},{"t":84.25,"who":"narrator","text":"Büyük emirler, sığ derinlik veya hızlı piyasalar sonucun beklentinden sapma olasılığını artırır. Emir vermeden önce tutara ve derinliğe, sonrasında ise gerçekleşen ortalamaya bak."},{"t":103.25,"who":"sam","text":"Hayır."},{"t":104.04,"who":"nexubo","text":"Ancak faturayı gördüğünde işlemin netleşir. Sadece ekrandaki en büyük sayıya odaklanma."},{"t":116.25,"who":"nexubo","text":"Komisyonlar gerçekten düşürebileceğin bir maliyettir. NexuAlpha'da ücretleri karşılaştır ve komisyon iadesi almak için kodumuzla partner bağlantısından kaydol. Düşük maliyet, aynı risk."},{"t":126.75,"who":"narrator","text":"Alış emri verdin ama hiçbir şey olmuyor. Sistem mi bozuldu? Gelecek bölümde: Piyasa, limit ve iptal."},{"t":132.45,"who":"narrator","text":"Önce anla, sonra harekete geç."}]},{"ep":14,"title":"Piyasa, limit, iptal: Her biri neyi çözer?","goal":"Bir emri 'önce gerçekleşme' veya 'önce fiyat sınırı' esasına göre seçin; gerçekleşmeyen ve kısmen gerçekleşen emirleri anlayın.","task":"Sanal bir limit emir verin, kısmi gerçekleşmeyi gözlemleyin ve ardından kalan miktarı iptal edin.","answer":"Fiyat koşulları uygun olsa bile mevcut miktar etkilidir; gerçekleşen kısımlar iptal ile geri alınamaz.","takeaways":["Piyasa emri şu an mevcut fiyatlardan hızla gerçekleşir; nihai fiyat kayabilir.","Limit emir fiyatınıza sınır koyar, ancak gerçekleşmeyebilir.","İptal yalnızca gerçekleşmemiş kısmı etkiler; gerçekleşen kısım kalır."],"quiz":{"q":"Limit emrinizin yarısı gerçekleşti ve emri iptal ettiniz. Ne olur?","options":["Her şey geri alınır","Yalnızca gerçekleşmemiş yarı iptal edilir","Gerçekleşen yarı piyasa emrine dönüşür"],"answer":1,"why":"İptal, gerçekleşmiş bir işlemi geri saramaz. Yalnızca kalan miktarı durdurur."},"transcript":[{"t":0.25,"who":"sam","text":"Al'a bastım. Neden bir türlü gerçekleşmiyor?"},{"t":9.25,"who":"nexubo","text":"Piyasa emirleri mevcut fiyatlardan hızla gerçekleşmeyi hedefler, ancak nihai fiyat değişebilir. Limit emirler belirli bir fiyattan daha yükseğe almamayı veya daha düşüğe satmamayı şart koşar, gerçekleşme garantisi vermez."},{"t":32.25,"who":"narrator","text":"Mevcut fiyatın altından almak istiyorsanız beklemeniz gerekebilir. Aksine, bir limit emir karşı tarafın koşullarını karşılıyorsa anında da gerçekleşebilir; her limit emir sırada beklemek zorunda değildir."},{"t":60.25,"who":"sam","text":"Yani iptal etmek az önce aldıklarımı da geri mi alır?"},{"t":62.82,"who":"nexubo","text":"Hayır. İptal yalnızca henüz gerçekleşmemiş kısmı etkiler; önceden gerçekleşen işlemler geri alınamaz."},{"t":84.25,"who":"narrator","text":"İşlem yapmadan önce durumu kontrol edin. Piyasa yapıcı veya alıcı olmanız emrin nasıl gerçekleştiğine bağlıdır; limit seçmek belirli bir ücret oranını garanti etmez."},{"t":103.25,"who":"sam","text":"Hayır."},{"t":104.12,"who":"nexubo","text":"Emir seçmek bir yürütme yöntemi seçmektir, dilek tutmak değil."},{"t":116.25,"who":"narrator","text":"Yeşil bir mum, bir sonrakinin de yükseleceği anlamına mı gelir? Gelecek bölümde."},{"t":121.05,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":15,"title":"Tek bir mum: Size söylediği dört şey nedir?","goal":"Açılış, en yüksek, en düşük, kapanış ve zaman dilimini okuyun; rengi veya tek bir şekli tahmin olarak görmeyin.","task":"Sanal mum üzerinde açılış, yüksek, düşük, kapanış değerlerine tıklayın ve grafik zaman dilimini onaylayın.","answer":"50,000 / 51,000 / 49,000 / 50,500; beş dakikalık periyot.","takeaways":["Bir mum, bir dönem için dört fiyat gösterir: açılış, en yüksek, en düşük ve kapanış.","Şekilden önce zaman dilimini okuyun: beş dakika bir gün değildir.","Renkler uygulamadan uygulamaya değişir ve tek bir mum bir kayıttır, tahmin değildir."],"quiz":{"q":"Beş dakikalık bir mum 50,000'den açılıyor, 51,000'e çıkıyor, 49,000'e iniyor ve 50,500'den kapanıyor. En yüksek fiyat nedir?","options":["50,500","51,000","49,000"],"answer":1,"why":"Üst fitilin tepesi o dönemdeki en yüksek fiyattır: 51,000."},"transcript":[{"t":0.25,"who":"sam","text":"Yeşil, bir sonraki saniyede de yükseleceği anlamına mı gelir?"},{"t":9.25,"who":"nexubo","text":"Bir mum bir zaman dilimindeki dört fiyatı kaydeder: Açılış, en yüksek, en düşük ve kapanış. Bu kurgusal bir beş dakikalık piyasadır, sonraki beş dakikanın garantisi değildir."},{"t":32.25,"who":"narrator","text":"Gövde açılış ile kapanış arasındaki farkı görmenizi sağlar; gölgeler ulaşılan en yüksek ve en düşük seviyeleri gösterir. Henüz kapanmamış bir mum, yeni işlemlerle değişmeye devam eder."},{"t":60.25,"who":"sam","text":"Zaman dilimini değiştirdiğimde grafik neden farklı görünüyor?"},{"t":63.75,"who":"nexubo","text":"Her mumun temsil ettiği süre değişti. Şekli yorumlamadan önce zaman dilimini okuyun; beş dakikayı bir gün gibi değerlendiremezsiniz."},{"t":84.25,"who":"narrator","text":"Farklı uygulamalar yükseliş ve düşüş için farklı renkler kullanabilir, bu yüzden göstergeye ve sayılara bakın. Geçmiş veriler bilgi verir, ancak tek bir mum sonraki hareketi garanti etmez."},{"t":103.25,"who":"sam","text":"En yüksek 51,000, kapanış 50,500."},{"t":108.91,"who":"nexubo","text":"Önce kaydı okuyun, kaydı bir kehanete dönüştürmeyin."},{"t":116.25,"who":"narrator","text":"\"1,000'im var, sadece 20 kaybetmek istiyorum, hepsini alayım mı?\" Sırada: Önce ne kadar kaybedebileceğinizi belirleyin."},{"t":122.35,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":16,"title":"Ne kadar alacağınıza karar vermeden önce ne kadar kaybedebileceğinizi belirleyin","goal":"Hesap bakiyesi, pozisyon büyüklüğü ve planlanan riskin üç farklı sayı olduğunu anlayın.","task":"Verilen giriş, zarar durdur mesafesi ve eğitim risk bütçesi ile sanal pozisyonu hesaplayın.","answer":"400 USDT nominal spot tutarı; 0.008 BTC; ücretler ve yürütme sapmaları ayrıca hesaplanmalıdır.","takeaways":["Hesap bakiyesi, pozisyon büyüklüğü ve planlanan risk üç farklı sayıdır.","Önce çıkışınıza karar verin, sonra pozisyonu boyutlandırın.","5% stop ve 20'lik risk bütçesiyle pozisyon yaklaşık 400 olur."],"quiz":{"q":"Giriş 50,000, planlanan çıkış 47,500 ve 20 kaybetmeyi kabul ediyorsunuz. Pozisyon yaklaşık ne kadar büyük?","options":["20","400","4,000"],"answer":1,"why":"Çıkış 5% uzakta ve 400'ün 5%'i 20'dir. Maliyetler bunun üzerine eklenir."},"transcript":[{"t":0.25,"who":"sam","text":"1,000'im var ve sadece 20 kaybetmek istiyorum, o zaman önce hepsini alayım mı?"},{"t":9.25,"who":"nexubo","text":"Hesapta ne kadar olduğu, bu işlemde ne kadar aldığınız ve planlanan maksimum risk üç farklı şeydir. Ancak bir çıkış planınız olduğunda pozisyon büyüklüğünü hesaplayabilirsiniz."},{"t":35.25,"who":"narrator","text":"Bir alıştırmaya bakalım: Giriş 50,000, planlanan çıkış 47,500, fark 5%. Maliyetleri göz ardı edip 20 birimlik fiyat riski almayı planlıyorsanız, pozisyon büyüklüğü yaklaşık 400'dür."},{"t":67.25,"who":"sam","text":"Yani 'en fazla 20 kaybetmek', 'sadece 20'lik almak' demek değil mi?"},{"t":70.55,"who":"nexubo","text":"Doğru. Burada 400'lük pozisyonun 5% düşmesi 20'ye denk gelir; bu sadece bir eğitim parametresidir."},{"t":95.25,"who":"narrator","text":"Gerçek piyasalarda kayma, fiyat boşlukları, ücretler veya işlem hataları olabilir; bu yüzden planlanan risk garantili bir tavan değildir. Kurs için borç almayın veya temel yaşam fonlarını pratik için kullanmayın."},{"t":116.25,"who":"sam","text":"Yirmi."},{"t":116.98,"who":"nexubo","text":"Bu işleme ihtiyacınız olup olmadığına bakmadan önce kabul edebileceğiniz en kötü durumu hesaplayın."},{"t":131.25,"who":"narrator","text":"Zarar durdur ayarlamak tam olarak bu miktarı kaybedeceğiniz anlamına mı gelir? Sırada: Zarar durdurmanın gerçeği."},{"t":137.75,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":17,"title":"Kâr al ve zarar durdur plandır, sigorta değil","goal":"Tetiklenme ile gerçekleşme arasındaki farkı ve stop-piyasa ile stop-limit emirlerinin farklı risklerini anlayın.","task":"Aynı sert düşüşte stop-piyasa ve stop-limit emirlerinin pratik sonuçlarını karşılaştırın.","answer":"İlki kayma yaşayabilir; ikincisi hiç gerçekleşmeyebilir. İkisi de anapara koruma sigortası değildir.","takeaways":["Zarar durdur (stop-loss) çıkış planınızı uygular; sigorta değildir.","Stop-market hızla çıkar ama hızlı bir piyasada kayabilir.","Stop-limit fiyatı sınırlar ama hiç gerçekleşmeyebilir."],"quiz":{"q":"Sert bir düşüşte bir stop-limit emre ne olabilir?","options":["Her zaman tetik fiyatından gerçekleşir","Fiyat hızla geçip giderse gerçekleşmeyebilir","Sigortaya dönüşür"],"answer":1,"why":"Limit fiyatınızı korur, bu yüzden piyasa hızlı hareket ettiğinde emir gerçekleşmeden kalabilir."},"transcript":[{"t":0.25,"who":"sam","text":"Zarar durdurum ayarlandı, yani sadece yazdığım tutarı kaybederim, değil mi?"},{"t":9.25,"who":"nexubo","text":"Zarar durdur koşullar sağlandığında bir çıkış planı yürütür, sigorta değildir. Koşulun tetiklenmesi tam o fiyattan gerçekleşeceği veya zararın tam orada duracağı anlamına gelmez."},{"t":32.25,"who":"narrator","text":"Tetiklendikten sonra piyasa fiyatından çalışarak hızla çıkmaya öncelik verir, ancak gerçekleşen fiyatta kayma olabilir. Hızlı hareketlerde veya düşük derinlikte fark daha da açılabilir."},{"t":60.25,"who":"nexubo","text":"Tetiklendikten sonra limit emir girer; kabul edilen fiyatı sınırlar ama fiyat hızla geçerse satılamayabilir. Biri diğerinden mutlak üstün değildir; farklı tercihlerdir."},{"t":84.25,"who":"narrator","text":"Ayarladıktan sonra yönü, miktarı ve emir durumunu kontrol edin. Vadeli işlemlerde, tasfiyenin daha önce tetiklenebileceği bir yere koymamak için hangi fiyat türünün tetiklediğini de doğrulayın."},{"t":103.25,"who":"sam","text":"Garanti değil."},{"t":104.72,"who":"nexubo","text":"Sınırları anlamak, zarar durdurmayı bir tılsım değil, etkili bir plan olarak kullanmanızı sağlar."},{"t":116.25,"who":"narrator","text":"İkisi de BTC yazıyor. Ancak biri size hiç bitcoin vermeyebilir. Sırada: Spot ve vadeli işlemler."},{"t":123.15,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz","goal":"Varlık sahibi olmak ile fiyat sözleşmesi sahibi olmayı ayırt edin; uzun ve kısa pozisyon yönlerini anlayın.","task":"Spot varlık bakiyesi ile vadeli işlem pozisyonu alanlarını doğru sayfalarla eşleştirin.","answer":"Vadeli işlem pozisyonu çekilebilir kripto varlıklarla eşdeğer değildir; kurs gerçek bir hesap açmanızı istemez.","takeaways":["Spot bir varlığı başka bir varlıkla takas eder; perpetual ise bir sözleşme pozisyonudur.","Long, fiyat yükselirse kazanır; short, fiyat düşerse kazanır; yanlış taraf kaybeder.","Vadeli işlemler farklı bir risk yapısıdır, ulaşmanız gereken bir seviye değildir."],"quiz":{"q":"Bir vadeli işlem pozisyonu size çekebileceğiniz bitcoin verir mi?","options":["Evet, spot ile aynıdır","Hayır, kâr ve zararı uzlaştıran bir sözleşmedir","Yalnızca 10x kaldıraçla"],"answer":1,"why":"Doğrusal bir perpetual, kâr ve zararı sözleşme içinde uzlaştırır. Çekilebilir bir coin bakiyesi değildir."},"transcript":[{"t":0.25,"who":"sam","text":"İkisi de Bitcoin yazıyor, aynı alım satım değil mi?"},{"t":9.25,"who":"nexubo","text":"Borçsuz sade spot, bir varlığı diğeriyle takas eder. Buradaki doğrusal sürekli sözleşmeler ise fiyat hareketlerine göre kâr-zarar hesabı yapan bir sözleşme pozisyonudur; çekilebilir bitcoin almak demek değildir."},{"t":32.25,"who":"narrator","text":"Uzun pozisyon genellikle fiyatın artmasını, kısa pozisyon ise düşmesini bekler. Yönü yanlış tahmin ederseniz iki taraf da zarar eder. Kısa pozisyon açabilmek, para kazanmanın daha kolay olduğu anlamına gelmez."},{"t":60.25,"who":"sam","text":"Spottan vadeli işlemlere geçmeli miyim?"},{"t":62.38,"who":"nexubo","text":"Gerek yok. Vadeli işlemler farklı bir risk yapısıdır, ulaşılması zorunlu bir seviye değildir; ne olduğunu bilip kullanmamayı da seçebilirsiniz."},{"t":84.25,"who":"narrator","text":"Borçsuz sade spotta vadeli sözleşmelerdeki gibi yetersiz teminat tasfiyesi yoktur, ancak varlık yine de ciddi değer kaybedebilir. Zorunlu tasfiyenin olmaması anaparanın korunduğu anlamına gelmez."},{"t":103.25,"who":"sam","text":"Hayır."},{"t":103.9,"who":"nexubo","text":"Kaldıraç üzerinde çalışmadan önce neyle işlem yaptığınızı ayırt edin."},{"t":116.25,"who":"narrator","text":"10x kaldıraçta borsa size 900 hibe mi eder? Gelecek bölümde."},{"t":121.25,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":19,"title":"10x kaldıraç: Daha fazla para mı, daha fazla risk mi?","goal":"Teminat, nominal pozisyon ve getiri oranını ayırt edin; sabit pozisyon büyüklüğünde kaldıraç ayarının etkilerini anlayın.","task":"Sabit teminat ve sabit pozisyon modlarını ayrı ayrı seçin; fiyat değişimlerinden sonra nakit kâr-zararı gözlemleyin.","answer":"Sabit teminatta kaldıracı artırmak nominal pozisyonu büyütür; sabit pozisyonda nakit kâr-zarar otomatik olarak büyümez.","takeaways":["1,000'lik bir pozisyonu kontrol eden 100 teminat, 10x kaldıraçtır.","Fiyat hareketleri pozisyona etki eder, sonucu teminatınız üstlenir.","Aynı pozisyon büyüklüğünde kaldıracı değiştirmek teminatı değiştirir, kâr/zararı değil."],"quiz":{"q":"1,000'lik bir pozisyon, ücretler hariç, aleyhinize 1% hareket ediyor. Yaklaşık ne kadar kaybedersiniz?","options":["1","10","100"],"answer":1,"why":"1,000'lik pozisyonun 1%'i yaklaşık 10'dur ve teminatınızdan düşülür."},"transcript":[{"t":0.25,"who":"sam","text":"On kat kaldıraç açınca borsa bana 900 hibe mi ediyor?"},{"t":9.25,"who":"nexubo","text":"Hibe para değildir. Basitçe anlatmak gerekirse, 100 birim teminatla 1,000 birimlik nominal pozisyonu kontrol etmek 10x kaldıraçtır. Fiyat hareketleri pozisyona etki eder ve teminatınız kâr-zararı karşılar."},{"t":35.25,"who":"narrator","text":"Ücretleri saymazsak, fiyat 1% aleyhinize hareket ettiğinde, 1,000'lik pozisyon yaklaşık 10, 2,000'lik pozisyon yaklaşık 20 kaybeder. Yüzde küçük görünse de küçük teminat için çok belirgin olabilir."},{"t":67.25,"who":"nexubo","text":"Sık yapılan bir hata daha: Pozisyon büyüklüğü değişmez ve sadece kaldıraç ayarını değiştirirseniz, nakit kâr-zarar durduk yere katlanmaz; asıl değişen şey teminat gereksinimi ve risk tamponudur."},{"t":95.25,"who":"narrator","text":"Gerçek tasfiye; sürdürme teminatı, gösterge fiyatı ve ücretleri içerir; 10x olması tam olarak 10% düşünce tasfiye olunacağı anlamına gelmez. Gerçek işlemlerinizi bu yaklaşıma göre ayarlamayın."},{"t":116.25,"who":"sam","text":"Hayır."},{"t":117.06,"who":"nexubo","text":"Büyüttüğü şey muhakeme yeteneğiniz değil, pozisyonun anaparanız üzerindeki etkisidir."},{"t":131.25,"who":"narrator","text":"Teminatınız sıfırlanmadan önce neden kapanabilirsiniz? Sırada: O görünmez çizgi."},{"t":137.05,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":20,"title":"Teminatınız sıfıra ulaşmadan önce pozisyonunuz neden kapatılabilir?","goal":"Başlangıç teminatı, sürdürme teminatı, özkaynak ve kullanılabilir bakiye arasındaki farkı anlayın.","task":"Başlangıç 100 ve gerçekleşmemiş zarar 20 iken (ücretsiz), basitleştirilmiş 80 özkaynağını doldurun; değişen alanları belirleyin.","answer":"Özkaynak 80; sürdürme gereksinimleri ürün kurallarına göre ayrıca hesaplanmalıdır, başlangıç teminatına eşit olduğu varsayılmamalıdır.","takeaways":["Başlangıç teminatı pozisyonu açar; sürdürme teminatı onu açık tutar.","Özkaynak, teminat artı veya eksi açık sonuçtur: 100'den 20 düşünce 80 kalır.","Risk sistemi, teminatınız sıfıra ulaşmadan önce devreye girebilir."],"quiz":{"q":"Başlangıç teminatı 100 ve pozisyon, ücretler hariç, 20 zararda. Basitleştirilmiş özkaynak nedir?","options":["100","80","120"],"answer":1,"why":"100 eksi 20 zarar 80 bırakır ve fiyat aleyhinize gitmeye devam ederse tampon küçülmeye devam eder."},"transcript":[{"t":0.25,"who":"sam","text":"Hâlâ bakiye var, neden beklememe izin verilmiyor?"},{"t":9.25,"who":"nexubo","text":"Pozisyon açmak başlangıç teminatı gerektirir; pozisyonu tutarken sürdürme teminatı gereksinimlerini de karşılamalısınız. Başlangıçta koyduğunuz tutar, sonradan aynı risk tamponuna sahip olacağınız anlamına gelmez."},{"t":35.25,"who":"narrator","text":"Diyelim ki başlangıç teminatı 100 ve gerçekleşmemiş zarar 20 olsun; diğer kalemleri saymazsak özkaynak 80 kalır. Fiyat aleyhte hareket etmeye devam ettikçe kullanılabilir tampon da küçülmeye devam eder."},{"t":67.25,"who":"nexubo","text":"Özkaynak platformun gerektirdiği sürdürme seviyesine yaklaştığında risk sistemi devreye girebilir; her şeyin sıfırlanmasını beklemesi gerekmez. Bu hesap türüne, teminat moduna ve ürün kurallarına bağlıdır."},{"t":95.25,"who":"sam","text":"O zaman sürekli para eklersem güvende mi olurum?"},{"t":99.06,"who":"nexubo","text":"Para eklemek fiyat yönünü değiştirmez veya tasfiye olmayacağınızı garanti etmez. Yalnızca daha fazla fonu aynı riskin içine çekebilir."},{"t":116.25,"who":"sam","text":"Hayır; biri açılış koşuluyla, diğeri pozisyon sürdürme gereksinimiyle ilgilidir."},{"t":121.2,"who":"nexubo","text":"Önce özkaynağa bakın, sonra uyarı çizgisinden ne kadar uzakta olduğunu görün."},{"t":131.25,"who":"narrator","text":"Küçük bir kutuya 100 koymak diğer 900'ü sonsuza dek güvende tutar mı? Sırada: İzole teminat."},{"t":137.95,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":21,"title":"İzole teminat: Bir işlemi kendi bağımsız kutusuna koymak","goal":"Pozisyon başına teminat izolasyonunu ve teminat eklemenin risk altındaki parayı nasıl artırabileceğini anlayın.","task":"Simülasyon ayarlarında otomatik ekleme anahtarını bulun ve risk üstlenen parayı neden değiştirdiğini açıklayın.","answer":"Otomatik veya manuel teminat ekleme taahhüt edilen teminatı artırır; yalnızca başlangıç miktarının kaybedileceği koşulsuz olarak vaat edilemez.","takeaways":["İzole teminat, tek bir pozisyona kendi teminatını verir.","Ayırdığınız teminat yine de kaybedilebilir; izole, bir zarar durdur değildir.","Otomatik ya da manuel ekleme, aynı riskin arkasına daha fazla paranızı koyar."],"quiz":{"q":"İzole bir pozisyon için otomatik teminat eklemeyi açıyorsunuz. Ne değişir?","options":["Hiçbir şey, zarar ilk 100 ile sınırlı kalır","Bakiyenizin daha fazlası pozisyona akabilir","Pozisyon risksiz hale gelir"],"answer":1,"why":"Otomatik ekleme, kullanılabilir bakiyeyi pozisyona taşır, böylece riski daha fazla para taşır."},"transcript":[{"t":0.25,"who":"sam","text":"İzole teminata 100 koyarsam, diğer 900'e sonsuza kadar dokunulmaz mı?"},{"t":9.25,"who":"nexubo","text":"İzole teminatın özü, pozisyona ayrı teminat tahsis etmektir. Ek teminat konulmadığı ve otomatik ekleme açılmadığı sürece, tasfiye riski esasen bu tahsis edilen teminatla sınırlıdır."},{"t":32.25,"who":"narrator","text":"Pozisyonların teminat kapsamını ayırmayı kolaylaştırır. Ancak bu 100'ün kendisi yine de kaybedilebilir; izole teminat zararı yok etmez veya bir zarar durdur emri değildir."},{"t":60.25,"who":"nexubo","text":"Bu düğmeye dikkat edin: Bazı borsalar otomatik teminat ekleme sunar. Açıldığında, kullanılabilir bakiye pozisyona akmaya devam edebilir. Manuel ekleme de aynıdır; daha fazla parayı riske sokar."},{"t":84.25,"who":"narrator","text":"Sadece 'izole' kelimesini görüp maksimum kaybın sonsuza kadar ilk 100 ile sınırlı olduğunu varsaymayın. Ekleme ayarlarını, ücretleri ve ürün kurallarını mutlaka kontrol edin."},{"t":103.25,"who":"sam","text":"Olamaz."},{"t":103.99,"who":"nexubo","text":"İzole teminat yalıtım sınırına bakar, ama aynı zamanda ek kanalların bağlı olup olmadığına da bakar."},{"t":116.25,"who":"narrator","text":"Bir pozisyondaki sızıntı diğerini de batırmaya başlar. Sırada: Çapraz teminat."},{"t":121.15,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":22,"title":"Çapraz teminat: Bir kayıp diğer pozisyonlarınızı neden vurabilir?","goal":"Tek bir teminat havuzunun paylaşılan riskini anlayın; çapraz teminatı tüm kişisel varlıklarınızla karıştırmayın.","task":"Bir sanal pozisyonun zarar etmesine izin verin, aynı havuzdaki riskin nasıl değiştiğini izleyin ve bu teminat havuzunda olmayan varlıkları daire içine alın.","answer":"Risk aynı teminat havuzuna yayılabilir. Tüm kişisel varlıklarınızı otomatik olarak kapsamaz.","takeaways":["Çapraz teminat, pozisyonlar arasında tek bir teminat havuzunu paylaşır.","Zarardaki tek bir pozisyon, diğerlerinin dayandığı tamponu tüketebilir.","Banka kartlarınıza veya kişisel cüzdanlarınıza uzanmaz."],"quiz":{"q":"Çapraz teminat otomatik olarak daha mı güvenlidir?","options":["Evet, asla tasfiye edilemez","Şart değil, paylaşılan havuza ve kurallara bağlıdır","Evet, tüm banka kartlarınızı kullanır"],"answer":1,"why":"Ek teminat risk müdahalesini geciktirebilir, ama aynı zamanda paranızın daha fazlasını riske atar."},"transcript":[{"t":0.25,"who":"sam","text":"Kayıp soldakinde. Sağdaki neden tehlikede?"},{"t":9.25,"who":"nexubo","text":"Çapraz teminat, kuralların izin verdiği ölçüde teminatı pozisyonlar arasında paylaşır. Burada bir teminat havuzunda 1,000 olduğunu varsayalım. Birden fazla pozisyon sadece ilk ayrılan tutara değil, bu havuza bağlı olabilir."},{"t":39.25,"who":"narrator","text":"Zarardaki bir pozisyon, diğer pozisyonların güvendiği tamponu eritebilir. Kârlar, zararlar, açık emirler için tutulan teminat ve teminatınızın değeri aynı hesabın riskini etkileyebilir."},{"t":75.25,"who":"sam","text":"Yani çapraz teminatta tasfiye olmak daha mı zor, bu onu daha mı güvenli yapar?"},{"t":79.67,"who":"nexubo","text":"Ekstra para, bir pozisyonun risk yönetimine girmesini geciktirebilir. Ancak kayıplar karşısında daha fazla paranızı riske atar."},{"t":106.25,"who":"narrator","text":"Çapraz teminat, bir platformun tüm banka kartlarınızı veya kişisel cüzdanlarınızı otomatik olarak kullanmasına izin vermez. Hangi hesapların ve teminatların sayılacağı ürün kurallarına bağlıdır. Karmaşık teminatlar değerleme kesintileri (haircut) ve kendi fiyat riskleriyle de gelebilir."},{"t":130.25,"who":"sam","text":"Kesinlikle öyle değil. Paylaşılan havuza ve hesap kurallarına bağlıdır."},{"t":135.19,"who":"nexubo","text":"Sadece tek bir pozisyonun kutusuna değil, tüm havuza bakın."},{"t":146.25,"who":"narrator","text":"İzlediğiniz fiyat çizgiye değmedi ama alarm çalıyor. Sırada: Tasfiye butonuna kim basıyor?"},{"t":152.55,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":23,"title":"Tasfiye: Zorunlu kapatma butonuna kim bastı?","goal":"Tasfiye tetikleyicilerini, gösterge fiyatını ve sürdürme gereksinimlerini anlayın; ters kaldıracı kesin bir formül olarak görmeyin.","task":"Düşüp ardından yükselen aynı sanal piyasayı oynatın; sade spotu ve basitleştirilmiş izole sözleşmeyi ayrı ayrı izleyin.","answer":"Fiyatın izlediği yol önemlidir. Yolda tasfiye edilen bir sözleşme, sonraki toparlanmayla geri gelmez.","takeaways":["Birçok perpetual, tasfiyeyi son işleme göre değil, işaret fiyatına (mark price) ve teminat kurallarına göre belirler.","Sürdürme gereksinimine yaklaşıldığında sistem pozisyonu küçültebilir veya kapatabilir.","Kapanan bir pozisyon, fiyat toparlandığında geri gelmez."],"quiz":{"q":"Kaldıraçlı bir pozisyon tasfiye edildi ve daha sonra fiyat yeniden yükseldi. Ne olur?","options":["Pozisyon kendiliğinden geri gelir","Kapalı kalır; izlenen yol önemliydi","Borsa zararı iade eder"],"answer":1,"why":"Zorla kapatıldıktan sonra pozisyon gitmiştir. Sonraki bir toparlanma yalnızca hâlâ pozisyonu tutana yarar."},"transcript":[{"t":0.25,"who":"sam","text":"Baktığım fiyat henüz oraya gelmedi. Alarm neden çalıyor?"},{"t":9.25,"who":"nexubo","text":"Son işlem fiyatı, tasfiyeyi belirlemek için her zaman kullanılan fiyat değildir. Birçok sürekli sözleşme, gösterge fiyatını ve teminat kurallarını kullanarak riski değerlendirir. Platformunuzun gerçekte hangi kuralları kullandığını kontrol edin."},{"t":35.25,"who":"narrator","text":"Fiyat pozisyonun aleyhine hareket ettiğinde, kayıplar özkaynağı eritir. Sürdürme gereksinimine yaklaşıldığında sistem emirleri iptal edebilir, pozisyonu azaltabilir veya zorla kapatabilir. Onayınızı beklemesi gerekmez."},{"t":67.25,"who":"nexubo","text":"Tasfiye genellikle bu zorunlu kapatma risk olayını ifade eder, telefonunuzun düğmesinin bozulmasını değil. Gerçek tetikleyici; ücretlere, sürdürme teminatına, teminat moduna ve daha fazlasına bağlıdır. 10x, tam olarak 10%'luk bir düşüş anlamına gelmez."},{"t":95.25,"who":"sam","text":"Sonradan tekrar yükseldi. Sadece geri gelmesini bekleyemez miyim?"},{"t":99.46,"who":"nexubo","text":"Kapatılan bir pozisyon kendiliğinden geri gelmez. Bir düşüş ve ardından gelen yükseliş, kaldıraçlı bir pozisyon ile sadece elinizde tuttuğunuz sade spot için çok farklı sonuçlanabilir."},{"t":116.25,"who":"sam","text":"Garanti değil."},{"t":117.73,"who":"nexubo","text":"Önemli olan sadece varış noktası değildir; bu yoldan sağ çıkıp çıkamayacağınızdır."},{"t":131.25,"who":"narrator","text":"Fiyat neredeyse hiç oynamadı ve kapatmadınız ama bakiyeniz düştü. Son bölüm sırada."},{"t":137.35,"who":"narrator","text":"Önce anla, sonra işlem yap."}]},{"ep":24,"title":"Fiyat sabit, bakiye düştü mü? Maliyetleri unutmadan son aşamayı tamamlayın","goal":"Fonlama oranlarının yönünü ve tabanını bilin, eksiksiz bir vadeli işlem risk kontrolü yapın ve işlem yapmamayı seçebilin.","task":"Bir dönemin 0.10 tutarındaki ücretini hesaplayın ve sanal vadeli işlem emri kontrol listesini tamamlayın. Gerçek emir API'leri çağrılmamalıdır.","answer":"Pozitif oran: Uzunlar öder, kısalar alır. Bu örnekteki ücret: 0.10. Tüm temel risk sorularını doğru yanıtlayarak veya açıkça işlem yapmamayı seçerek geçin.","takeaways":["Fonlama, long ve short'lar arasında ödenir; borsaya ödenen sabit bir ücret değildir.","Pozisyon değerine göre hesaplanır: 1,000 için 0.01% oran 0.10 eder.","İşlem yapmamayı seçmek de geçer bir cevaptır."],"quiz":{"q":"Fonlama oranı pozitif. Genellikle kim öder?","options":["Short'lar long'lara öder","Long'lar short'lara öder","Herkes borsaya öder"],"answer":1,"why":"Pozitif oranda genellikle long'lar short'lara öder. Negatif oranda durum tersine döner."},"transcript":[{"t":0.25,"who":"sam","text":"Fiyat neredeyse hiç oynamadı ve kapatmadım. Bakiyem neden daha düşük?"},{"t":9.25,"who":"nexubo","text":"İşlem ücretlerinin yanı sıra sürekli sözleşmelerde genellikle bir fonlama mekanizması bulunur. Oran pozitif olduğunda uzunlar genellikle kısalara ödeme yapar. Negatif olduğunda durum tersine döner. Herkesin borsaya ödediği sabit bir faiz değildir."},{"t":42.25,"who":"narrator","text":"Diyelim ki uzlaşma anında pozisyon değeri 1,000 ve oran 0.01% olsun. Bu ücret 0.10'dur. Pozisyon değerine göre hesaplanır, ilk 100 teminatınıza göre değil."},{"t":83.25,"who":"nexubo","text":"Aralık ve oran çifte, platforma ve piyasaya göre değişebilir. Bunu 'her sözleşmede, her sekiz saatte bir, sonsuza kadar' diye ezberlemeyin. Ve fonlama almayı risksiz bir gelir gibi görmeyin."},{"t":117.25,"who":"narrator","text":"Son seviye yalnızca pratik içindir. Önce neyle ve hangi yönde işlem yaptığınızı açıklayın. Ardından modu, büyüklüğü, teminatı, otomatik eklemeyi, çıkış planını ve maliyetleri kontrol edin. Anlamadığınız tek bir madde bile varsa durun. Düğmelere basarak tahmin yürütmeyin."},{"t":144.25,"who":"sam","text":"Nasıl yapılacağını biliyorum ve bu riskin bana uygun olmadığını biliyorum. Bu yüzden işlem yapmayacağım."},{"t":149.09,"who":"nexubo","text":"Bu da geçerli bir sonuçtur. Kursu bitirmek para kazanabileceğiniz anlamına gelmez. Önce anla, sonra işlem yap."},{"t":161.25,"who":"nexubo","text":"Ne işlem yaparsanız yapın, komisyonlar birikir. NexuAlpha'da ücretleri karşılaştırın ve komisyonlarınızın bir kısmını geri almak için kodumuzla resmi bir ortaklık bağlantısı üzerinden kaydolun. Daha düşük maliyet, aynı risk."},{"t":172.75,"who":"narrator","text":"İki sezonu da bitirdiniz. En zor bulduğunuz bölümü seçin ve işlem yapmadan önce tekrar izleyin."},{"t":178.65,"who":"narrator","text":"Önce anla, sonra işlem yap."}]}]});
